-- SEC-003 assertions are mandatory failures, never expected-gap TODOs.
RESET ROLE;
SELECT ok((SELECT convalidated AND cardinality(conkey)=2 FROM pg_constraint WHERE conname='contacts_project_id_fkey' AND connamespace='public'::regnamespace), 'contacts project/owner composite foreign key is validated');
SELECT ok((SELECT convalidated AND cardinality(conkey)=2 FROM pg_constraint WHERE conname='interviews_project_id_fkey' AND connamespace='public'::regnamespace), 'interviews project/owner composite foreign key is validated');
SELECT ok((SELECT convalidated AND cardinality(conkey)=2 FROM pg_constraint WHERE conname='learnings_project_id_fkey' AND connamespace='public'::regnamespace), 'learnings project/owner composite foreign key is validated');
SELECT ok((SELECT convalidated AND cardinality(conkey)=2 FROM pg_constraint WHERE conname='experiments_project_id_fkey' AND connamespace='public'::regnamespace), 'experiments project/owner composite foreign key is validated');
SELECT ok((SELECT convalidated AND cardinality(conkey)=2 FROM pg_constraint WHERE conname='outreach_project_id_fkey' AND connamespace='public'::regnamespace), 'outreach project/owner composite foreign key is validated');
SELECT ok((SELECT convalidated AND cardinality(conkey)=3 FROM pg_constraint WHERE conname='interviews_contact_id_fkey' AND connamespace='public'::regnamespace), 'interview contact/project/owner composite foreign key is validated');
SELECT is((SELECT count(*) FROM pg_trigger WHERE tgname='enforce_private_identity' AND tgenabled='O'), 6::bigint, 'identity guard enabled on all six legacy tables');
SELECT ok(NOT (SELECT prosecdef FROM pg_proc WHERE oid='firstten_private.enforce_private_identity()'::regprocedure), 'identity trigger is security invoker');
SELECT ok(NOT has_function_privilege('authenticated','firstten_private.enforce_private_identity()','EXECUTE'), 'authenticated cannot directly execute identity helper');
SELECT ok(NOT has_function_privilege('anon','firstten_private.enforce_private_identity()','EXECUTE'), 'anonymous cannot directly execute identity helper');
SELECT ok(NOT has_schema_privilege('authenticated','firstten_private','USAGE'), 'private helper schema is not exposed to authenticated users');
SELECT firstten_policy_test.set_actor('owner_a');
SET LOCAL ROLE authenticated;
SELECT is(current_user::text, 'authenticated', 'SEC-003 actor is authenticated');
SELECT is(auth.uid(), firstten_policy_test.id('owner_a'), 'SEC-003 actor has owner A subject');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.projects SET id=gen_random_uuid() WHERE id=firstten_policy_test.id('project_a')$case$), 'error:23514', 'projects id cannot be rewritten');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.projects SET created_at=created_at + interval '1 second' WHERE id=firstten_policy_test.id('project_a')$case$), 'error:23514', 'projects created_at cannot be rewritten');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.contacts SET id=gen_random_uuid() WHERE id=firstten_policy_test.id('contact_a')$case$), 'error:23514', 'contacts id cannot be rewritten');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.contacts SET created_at=created_at + interval '1 second' WHERE id=firstten_policy_test.id('contact_a')$case$), 'error:23514', 'contacts created_at cannot be rewritten');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.contacts SET project_id=firstten_policy_test.id('project_a2') WHERE id=firstten_policy_test.id('contact_a')$case$), 'error:23514', 'contacts cannot move to another project owned by the same actor');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.interviews SET id=gen_random_uuid() WHERE id=firstten_policy_test.id('interview_a')$case$), 'error:23514', 'interviews id cannot be rewritten');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.interviews SET created_at=created_at + interval '1 second' WHERE id=firstten_policy_test.id('interview_a')$case$), 'error:23514', 'interviews created_at cannot be rewritten');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.interviews SET project_id=firstten_policy_test.id('project_a2') WHERE id=firstten_policy_test.id('interview_a')$case$), 'error:23514', 'interviews cannot move to another project owned by the same actor');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.learnings SET id=gen_random_uuid() WHERE id=firstten_policy_test.id('learning_a')$case$), 'error:23514', 'learnings id cannot be rewritten');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.learnings SET created_at=created_at + interval '1 second' WHERE id=firstten_policy_test.id('learning_a')$case$), 'error:23514', 'learnings created_at cannot be rewritten');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.learnings SET project_id=firstten_policy_test.id('project_a2') WHERE id=firstten_policy_test.id('learning_a')$case$), 'error:23514', 'learnings cannot move to another project owned by the same actor');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.experiments SET id=gen_random_uuid() WHERE id=firstten_policy_test.id('experiment_a')$case$), 'error:23514', 'experiments id cannot be rewritten');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.experiments SET created_at=created_at + interval '1 second' WHERE id=firstten_policy_test.id('experiment_a')$case$), 'error:23514', 'experiments created_at cannot be rewritten');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.experiments SET project_id=firstten_policy_test.id('project_a2') WHERE id=firstten_policy_test.id('experiment_a')$case$), 'error:23514', 'experiments cannot move to another project owned by the same actor');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.outreach SET id=gen_random_uuid() WHERE id=firstten_policy_test.id('outreach_a')$case$), 'error:23514', 'outreach id cannot be rewritten');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.outreach SET created_at=created_at + interval '1 second' WHERE id=firstten_policy_test.id('outreach_a')$case$), 'error:23514', 'outreach created_at cannot be rewritten');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.outreach SET project_id=firstten_policy_test.id('project_a2') WHERE id=firstten_policy_test.id('outreach_a')$case$), 'error:23514', 'outreach cannot move to another project owned by the same actor');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.interviews SET contact_id=firstten_policy_test.id('contact_b') WHERE id=firstten_policy_test.id('interview_a')$case$), 'error:23503', 'interview cannot change contact to another owner');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.interviews SET contact_id=firstten_policy_test.id('contact_a2') WHERE id=firstten_policy_test.id('interview_a')$case$), 'error:23503', 'interview cannot change contact to another project of same owner');
SELECT is(firstten_policy_test.attempt($case$INSERT INTO public.contacts(id,project_id,first_name) VALUES ('f3000000-0000-4000-8000-000000000001',firstten_policy_test.id('project_a'),'Same-project fixture')$case$), 'ok:1', 'same-project contact insertion remains allowed');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.interviews SET contact_id='f3000000-0000-4000-8000-000000000001' WHERE id=firstten_policy_test.id('interview_a')$case$), 'ok:1', 'interview may select another contact within its original owner/project');
RESET ROLE;
CREATE TABLE firstten_policy_test.interview_before_delete AS SELECT id,user_id,project_id,created_at,answers,tags,completed FROM public.interviews WHERE id=firstten_policy_test.id('interview_a');
GRANT SELECT ON firstten_policy_test.interview_before_delete TO authenticated;
SET LOCAL ROLE authenticated;
SELECT is(firstten_policy_test.attempt($case$DELETE FROM public.contacts WHERE id='f3000000-0000-4000-8000-000000000001'$case$), 'ok:1', 'contact deletion remains allowed');
SELECT ok((SELECT contact_id IS NULL FROM public.interviews WHERE id=firstten_policy_test.id('interview_a')), 'contact deletion clears only nullable contact_id');
SELECT is((SELECT to_jsonb(t) FROM (SELECT id,user_id,project_id,created_at,answers,tags,completed FROM public.interviews WHERE id=firstten_policy_test.id('interview_a')) t), (SELECT to_jsonb(t) FROM firstten_policy_test.interview_before_delete t), 'contact deletion preserves interview identity, scope and content');
SELECT is(firstten_policy_test.attempt($case$INSERT INTO public.interviews(project_id,contact_id) VALUES(firstten_policy_test.id('project_a'),NULL)$case$), 'ok:1', 'interviews may still have no contact');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.interviews SET contact_id=firstten_policy_test.id('contact_a') WHERE id=firstten_policy_test.id('interview_a')$case$), 'ok:1', 'same-project contact can be reattached');
SELECT is(firstten_policy_test.attempt($case$DELETE FROM public.projects WHERE id=firstten_policy_test.id('project_a')$case$), 'ok:1', 'project deletion still cascades through private children');
SELECT is(firstten_policy_test.visible_count('projects',firstten_policy_test.id('project_a')), 0::bigint, 'project cascade removes its projects row');
SELECT is(firstten_policy_test.visible_count('contacts',firstten_policy_test.id('contact_a')), 0::bigint, 'project cascade removes its contacts row');
SELECT is(firstten_policy_test.visible_count('interviews',firstten_policy_test.id('interview_a')), 0::bigint, 'project cascade removes its interviews row');
SELECT is(firstten_policy_test.visible_count('learnings',firstten_policy_test.id('learning_a')), 0::bigint, 'project cascade removes its learnings row');
SELECT is(firstten_policy_test.visible_count('experiments',firstten_policy_test.id('experiment_a')), 0::bigint, 'project cascade removes its experiments row');
SELECT is(firstten_policy_test.visible_count('outreach',firstten_policy_test.id('outreach_a')), 0::bigint, 'project cascade removes its outreach row');
SELECT is(firstten_policy_test.visible_count('projects',firstten_policy_test.id('project_a2')), 1::bigint, 'project cascade leaves another owned project intact');
SELECT is(firstten_policy_test.visible_count('contacts',firstten_policy_test.id('contact_a2')), 1::bigint, 'project cascade leaves another project contact intact');
RESET ROLE;
SELECT is((SELECT count(*) FROM public.projects WHERE id=firstten_policy_test.id('project_b')), 1::bigint, 'project cascade leaves other owner project intact');
GRANT USAGE ON SCHEMA firstten_policy_test TO service_role;
GRANT SELECT ON firstten_policy_test.ids TO service_role;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA firstten_policy_test TO service_role;
SET LOCAL ROLE service_role;
SELECT is(current_user::text, 'service_role', 'service role identity guard test uses actual database role');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.projects SET user_id=firstten_policy_test.id('owner_a') WHERE id=firstten_policy_test.id('project_b')$case$), 'error:42501', 'service role cannot silently transfer project ownership');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.contacts SET project_id=firstten_policy_test.id('project_a2') WHERE id=firstten_policy_test.id('contact_b')$case$), 'error:23514', 'service role cannot silently retarget private child scope');
RESET ROLE;
